#!/usr/bin/env bash
# recipes/crate-redox-syscall--0-2-16/build.sh -- stage the redox_syscall 0.2.16 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/redox_syscall-0.2.16"
